func (q *Queries) UpdateRepository(ctx context.Context, arg UpdateRepositoryParams) (UpdateRepositoryRow, error) {
	row := q.db.QueryRowContext(ctx, updateRepository,
		arg.ID,
		arg.Name,
		arg.Slug,
		arg.DefaultBranch,
		arg.SyncState,
		arg.TeamID,
	)
	var i UpdateRepositoryRow
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.TeamID,
		&i.Name,
		&i.Slug,
		&i.Provider,
		&i.ProviderID,
		&i.DefaultBranch,
		&i.SyncState,
		&i.RetentionArtifactBytes,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
